<?php

namespace Drupal\ash_salesforce\Salesforce;

/**
 * Reads a Web-to-Case or Web-to-Lead form generated by Salesforce.
 *
 * The generated HTML is the only description of the org we get without API
 * access: its action is the endpoint, its hidden inputs identify the org, and
 * its fields carry the IDs, labels, lengths and picklist values to post.
 */
class FormParser {

  /**
   * Inputs that steer the browser rather than describe the record.
   */
  protected const IGNORED = ['retURL', 'debug', 'debugEmail', 'encoding', 'submit'];

  /**
   * Standard fields the generator leaves out unless asked, by form kind.
   *
   * Offered as constants only: they're how a client tags where a record came
   * from, which a site form has no field for.
   */
  protected const STANDARD = [
    'case' => [
      'origin' => 'Case Origin',
      'type' => 'Type',
      'reason' => 'Case Reason',
      'priority' => 'Priority',
    ],
    'lead' => [
      'lead_source' => 'Lead Source',
    ],
  ];

  /**
   * Parses generated form HTML.
   *
   * @throws \InvalidArgumentException
   *   When the HTML holds no Web-to-Case or Web-to-Lead form.
   */
  public function parse(string $html): ParsedForm {
    $dom = new \DOMDocument();
    $previous = libxml_use_internal_errors(TRUE);
    // The generator emits unquoted attributes and stray comments, which only
    // the lenient HTML parser accepts. The prefix makes it read UTF-8.
    $dom->loadHTML('<?xml encoding="UTF-8">' . $html);
    libxml_clear_errors();
    libxml_use_internal_errors($previous);

    $xpath = new \DOMXPath($dom);
    $form = $xpath->query('//form')->item(0);
    $action = $form instanceof \DOMElement ? trim($form->getAttribute('action')) : '';
    $kind = match (TRUE) {
      str_contains($action, 'WebToCase') => 'case',
      str_contains($action, 'WebToLead') => 'lead',
      default => NULL,
    };
    if (!$kind || !preg_match('#^https://[^/]+\.salesforce\.com/#', $action)) {
      throw new \InvalidArgumentException('No Salesforce Web-to-Case or Web-to-Lead form found.');
    }

    $labels = [];
    foreach ($xpath->query('.//label[@for]', $form) as $label) {
      $labels[$label->getAttribute('for')] = $this->clean($label->textContent);
    }

    $params = [];
    $fields = [];
    foreach ($xpath->query('.//input|.//select|.//textarea', $form) as $input) {
      $name = $input->getAttribute('name');
      $type = $input->nodeName === 'input' ? strtolower($input->getAttribute('type') ?: 'text') : $input->nodeName;
      if ($name === '' || in_array($name, self::IGNORED, TRUE) || in_array($type, ['submit', 'button', 'reset'], TRUE)) {
        continue;
      }
      if ($type === 'hidden') {
        $params[$name] = $input->getAttribute('value');
        continue;
      }

      $options = [];
      if ($type === 'select') {
        foreach ($xpath->query('.//option', $input) as $option) {
          if (($value = $option->getAttribute('value')) !== '') {
            $options[$value] = $this->clean($option->textContent);
          }
        }
      }
      // The generator gives its textarea no id, only a label for its name.
      $label = $labels[$input->getAttribute('id') ?: $name] ?? $this->precedingText($input) ?: $name;
      $maxlength = $input->getAttribute('maxlength');
      $key = $this->key($name, $label, $fields);
      $fields[$key] = new Field($key, $name, $label, $type, $maxlength === '' ? NULL : (int) $maxlength, $options);
    }

    $standard = [];
    foreach (self::STANDARD[$kind] as $name => $label) {
      if (!isset($fields[$name])) {
        $standard[$name] = new Field($name, $name, $label, 'text', NULL, []);
      }
    }

    return new ParsedForm($kind, $action, $params, $fields, $standard);
  }

  /**
   * A field's key in mappings, the same in every org.
   *
   * Standard fields keep their name. A custom field's name is an ID unique to
   * its org, so it's keyed by its label: the UAT and production forms then
   * share one mapping.
   */
  protected function key(string $name, string $label, array $taken): string {
    if (!preg_match('/^00N[A-Za-z0-9]{12,15}$/', $name)) {
      return $name;
    }
    $key = trim(preg_replace('/[^a-z0-9]+/', '_', strtolower($label)), '_') ?: $name;
    return isset($taken[$key]) ? $key . '_' . $name : $key;
  }

  /**
   * The text just before an input, which is how custom fields are labelled.
   */
  protected function precedingText(\DOMNode $node): string {
    for ($sibling = $node->previousSibling; $sibling; $sibling = $sibling->previousSibling) {
      if ($sibling instanceof \DOMText && ($text = $this->clean($sibling->textContent)) !== '') {
        return $text;
      }
      if ($sibling instanceof \DOMElement && $sibling->nodeName !== 'br') {
        break;
      }
    }
    return '';
  }

  /**
   * Collapses whitespace and drops a trailing colon.
   */
  protected function clean(string $text): string {
    return rtrim(trim(preg_replace('/\s+/u', ' ', $text)), ':');
  }

}
